import java.io.*;class Note implements Serializable{private static final long serialVersionUID=1L;String text;Note(String t){text=t;}}public class SaveReloadTest{public static void main(String[]x)throws Exception{try(ObjectOutputStream o=new ObjectOutputStream(new FileOutputStream("notes.dat"))){o.writeObject(new Note("Persist me"));}try(ObjectInputStream i=new ObjectInputStream(new FileInputStream("notes.dat"))){Note n=(Note)i.readObject();if(!"Persist me".equals(n.text))throw new AssertionError();System.out.println("Save/reload test passed: "+n.text);}}}
